{
  "decision-first-peak-of-simultaneous-waiting": "WITH RECURSIVE seconds(sec) AS (SELECT 100 UNION ALL SELECT sec + 1 FROM seconds WHERE sec < 159), occupancy AS (SELECT w.queue_code, s.sec, COUNT(DISTINCT w.wait_key) AS peak_calls FROM seconds AS s JOIN call_waits AS w ON w.enter_sec <= s.sec AND (w.leave_sec IS NULL OR s.sec < w.leave_sec) GROUP BY w.queue_code, s.sec), ranked AS (SELECT queue_code, peak_calls, sec, ROW_NUMBER() OVER (PARTITION BY queue_code ORDER BY peak_calls DESC, sec ASC) AS rn FROM occupancy) SELECT queue_code, peak_calls, sec AS first_peak_sec FROM ranked WHERE rn = 1 ORDER BY queue_code ASC",
  "decision-fit-booklet-files-to-press-stock": "SELECT c.cover_id, i.insert_id, MIN(c.quality_pts, i.quality_pts) AS grade_points, c.sheet_qty + i.sheet_qty AS sheets_used FROM cover_options AS c JOIN insert_options AS i ON i.width_mm = c.width_mm WHERE c.sheet_qty + i.sheet_qty <= 100 ORDER BY grade_points DESC, (c.quality_pts + i.quality_pts) DESC, sheets_used ASC, c.cover_id COLLATE BINARY ASC, i.insert_id COLLATE BINARY ASC LIMIT 1",
  "decision-fit-catalog-pages-under-byte-cap": "WITH files AS (SELECT s.rows_per_file, 1 + (r.seq_no - 1) / s.rows_per_file AS file_no, MIN(r.seq_no) AS first_seq, MAX(r.seq_no) AS last_seq, 2 + SUM(r.row_bytes) AS file_bytes FROM split_setting AS s CROSS JOIN catalog_row AS r GROUP BY s.rows_per_file, file_no), chosen AS (SELECT rows_per_file FROM files GROUP BY rows_per_file HAVING MAX(file_bytes) <= 13 ORDER BY COUNT(*) ASC, rows_per_file ASC LIMIT 1) SELECT f.rows_per_file, f.file_no, f.first_seq, f.last_seq, f.file_bytes FROM files AS f JOIN chosen USING (rows_per_file) ORDER BY f.file_no ASC",
  "decision-fit-cited-corrections-into-stoppress-space": "WITH candidates(ids, copies, lines) AS (SELECT docket_id, copy_count, line_count FROM correction_docket WHERE line_count <= 6 UNION ALL SELECT a.docket_id || b.docket_id, a.copy_count + b.copy_count, a.line_count + b.line_count FROM correction_docket AS a JOIN correction_docket AS b ON a.docket_id COLLATE BINARY < b.docket_id AND a.bundle_code <> b.bundle_code WHERE a.line_count + b.line_count <= 6), chosen AS (SELECT ids FROM candidates ORDER BY copies DESC, lines ASC, ids COLLATE BINARY ASC LIMIT 1) SELECT d.docket_id, d.copy_count AS copies_reached, n.source_id FROM chosen AS c JOIN correction_docket AS d ON instr(c.ids, d.docket_id) > 0 JOIN primary_note AS n ON n.source_id = d.note_id ORDER BY d.docket_id COLLATE BINARY ASC"
}
